  function season(date) { const m = Number((date || '2026-01-01').slice(5, 7)); return m >= 3 && m <= 5 ? '봄 · 새로 자라는 마음' : m >= 6 && m <= 8 ? '여름 · 조금 길어진 하루' : m >= 9 && m <= 11 ? '가을 · 차곡차곡 익는 시간' : '겨울 · 천천히 시작하는 날'; }
